SINA_SMART["physics1-fluid-transfers"] = {"lecture":"physics1-fluid-transfers","title":"Fluid transfers in the organism","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-fluid-transfers:e0","text":"Intracellular ≈ 40% (28 L); interstitial ≈ 15%; plasma ≈ 4% (3 L); lymph 1-2%.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e1","text":"Dialysis membranes: flow driven by hydrostatic vs oncotic pressures.","topic":"Starling's law","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e2","text":"Starling: Φ = K·S(P₁ − P₂ − π₁ + π₂).","topic":"Starling's law","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e3","text":"Plasma oncotic pressure ≈ 28 mmHg.","topic":"Starling's law","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e7","text":"Oedema: ↑ capillary pressure or ↓ oncotic pressure.","topic":"Starling's law","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e4","text":"Gut between meals: +10 (absorption); digestion: +108.","topic":"Intestine and capillaries","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e5","text":"Capillary P > 30 mmHg in gut → exudation, diarrhoea.","topic":"Intestine and capillaries","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-fluid-transfers:e6","text":"Capillary arterial end +7 (filtration, nutritive); venous end −8 (reabsorption).","topic":"Intestine and capillaries","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"e4azfv":"a","1d1ekhn":"a","okc5m8":"a","b8q5uq":"a","1nuvzsu":"a","yd00qn":"a","s5l5zn":"a","18npqvv":"a","spfo3v":"a","g0xe25":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-fluid-transfers:e0":{"s":0,"u":["Intracellular ≈ 40% (28 L); interstitial ≈ 15%; plasma ≈ 4% (3 L); lymph 1-2%.","Water (60-65% of body weight) is exchanged between compartments: intracellular ≈ 40% (≈ 28 L in a 70 kg adult); extracellular ≈ 20-21% (interstitial ≈ 15%, 10-11 L; plasma ≈ 4%, 3 L; lymph 1-2%).","Transfers happen between the outside world and plasma (gut), plasma and interstitium (capillaries), and plasma and outside (kidney), through dialysis-like membranes driven by hydrostatic and oncotic pressures, and through semipermeable membranes (red cells) driven by osmosis."],"dp":[]},"physics1-fluid-transfers:e1":{"s":1,"u":["Dialysis membranes: flow driven by hydrostatic vs oncotic pressures.","For a dialysis membrane (passes water and small solutes, not proteins), the effective osmotic pressure is the oncotic pressure π , and flow results from competition with hydrostatic pressure P : Φ₁→₂ = K·S·(P₁ − P₂ − π₁ + π₂) (K permeability, S exchange area)."],"dp":[]},"physics1-fluid-transfers:e2":{"s":1,"u":["Starling: Φ = K·S(P₁ − P₂ − π₁ + π₂)."],"dp":[]},"physics1-fluid-transfers:e3":{"s":1,"u":["Plasma oncotic pressure ≈ 28 mmHg.","Plasma oncotic pressure ≈ 28 mmHg (albumin concentration, excluded volume, Donnan effect); it can be raised by IV linear macromolecules.","For a dialysis membrane (passes water and small solutes, not proteins), the effective osmotic pressure is the oncotic pressure π , and flow results from competition with hydrostatic pressure P : Φ₁→₂ = K·S·(P₁ − P₂ − π₁ + π₂) (K permeability, S exchange area)."],"dp":[]},"physics1-fluid-transfers:e7":{"s":1,"u":["Oedema: ↑ capillary pressure or ↓ oncotic pressure.","For a dialysis membrane (passes water and small solutes, not proteins), the effective osmotic pressure is the oncotic pressure π , and flow results from competition with hydrostatic pressure P : Φ₁→₂ = K·S·(P₁ − P₂ − π₁ + π₂) (K permeability, S exchange area).","Plasma oncotic pressure ≈ 28 mmHg (albumin concentration, excluded volume, Donnan effect); it can be raised by IV linear macromolecules."],"dp":[]},"physics1-fluid-transfers:e4":{"s":2,"u":["Gut between meals: +10 (absorption); digestion: +108.","During digestion (P lumen ≈ 100 mmHg): +108, optimal absorption.","Intestinal absorption (villi as dialysis membrane): between meals, lumen P = 2, π = 0 (digested proteins); capillary P = 20, π = 28 → Φ = K·S(2 − 20 − 0 + 28) = +10 : absorption."],"dp":[]},"physics1-fluid-transfers:e5":{"s":2,"u":["Capillary P > 30 mmHg in gut → exudation, diarrhoea.","In intestinal congestion (capillary P > 20) absorption falls; above ~30 mmHg flow reverses: water exudes ( diarrhoea )."],"dp":[]},"physics1-fluid-transfers:e6":{"s":2,"u":["Capillary arterial end +7 (filtration, nutritive); venous end −8 (reabsorption).","Capillary exchange : blood P = 35 (arterial end) or 20 (venous end), π = 28; interstitium P = 6, π = 6.","Arterial end: 35 − 6 + 6 − 28 = +7 → filtration to the tissues ( nutritive ); venous end: 20 − 6 + 6 − 28 = −8 → reabsorption (removal of metabolic waste); excess filtered fluid returns via lymph."],"dp":[{"h":"Why capillaries both feed and drain tissues","t":"Blood pressure falls along the capillary from about 35 to 20 mmHg while the oncotic pressure of plasma proteins stays near 28 mmHg. At the arterial end pressure wins and fluid carrying nutrients leaves; at the venous end oncotic pull wins and fluid carrying waste returns. The small excess left behind is collected by lymphatics. Source: the lecture's capillary exchange calculation."}]}},"meta":{"e4azfv":{"a":"recall","vg":"physics1-fluid-transfers:e0/recall/1"},"1d1ekhn":{"a":"recall","vg":"physics1-fluid-transfers:e0/recall/2"},"okc5m8":{"a":"recall","vg":"physics1-fluid-transfers:e1/recall/1"},"b8q5uq":{"a":"recall","vg":"physics1-fluid-transfers:e2/recall/1"},"1nuvzsu":{"a":"relationship","vg":"physics1-fluid-transfers:e4/relationship/1"},"yd00qn":{"a":"relationship","vg":"physics1-fluid-transfers:e7/relationship/1"},"s5l5zn":{"a":"application","vg":"physics1-fluid-transfers:e5/application/1"},"18npqvv":{"a":"recall","vg":"physics1-fluid-transfers:e6/recall/1"},"spfo3v":{"a":"recall","vg":"physics1-fluid-transfers:e6/recall/2"},"g0xe25":{"a":"recall","vg":"physics1-fluid-transfers:e7/recall/1"}},"explRev":"98133b629e41"};
